const consumer = kafka.consumer({ groupId: 'billing-ledger' })   // durable identity
await consumer.connect()
await consumer.subscribe({ topics: ['orders'], fromBeginning: true })
await consumer.run({
  eachMessage: async ({ message }) => {
    await handle(message.value)      // at-least-once: keep the handler idempotent
  },
})

