const client = mqtt.connect('mqtt://broker', {
  clientId: 'billing-ledger',   // must be stable
  clean: false,                 // keep the session while offline
})
client.on('connect', (connack) => {
  if (!connack.sessionPresent) console.warn('session lost - backlog gone')
  client.subscribe('orders/#', { qos: 1 })
})
